/// <summary>
/// METCPIRepricingTaskService
/// Task service class responsible for executing CPI-driven Sales Order repricing.
/// Retrieves eligible orders from the repricing queue, applies pricing resets, and updates order statuses.
/// </summary>
class METCPIRepricingTaskService extends METSysOperationTaskService
{
    guid topPickingProcessId;
    SalesId salesId;
    boolean cpIFlag;

}

Method.Source:
/// <summary>
/// Entry point for processing CPI repricing using the provided contract.
/// </summary>
/// <param name="_contract">The CPI repricing data contract.</param>
public void process(METCPIRepricingContract _contract)
{
    cpIFlag = _contract.parmCPIFlag();

    this.processInternal(_contract);

}

/// <summary>
/// Initializes the task service by retrieving the process identifier from the contract.
/// </summary>
protected void initialise()
{
    METCPIRepricingContract contract;

    super();

    // get the topPickingProcessId from the contract
    contract            = dataContract as METCPIRepricingContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Runs the task service loop, retrieving Sales Orders from the repricing queue
/// and executing repricing logic until all eligible records are processed.
/// </summary>
/// <param name="_readPast">Boolean flag indicating whether past records should be read.</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            this.execute();
        }
        catch (Exception::Error)
        {
            // Catch any exception so that one error won't stop the entire repricing process.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Retrieves the next Sales Order from the CPI repricing queue for processing.
/// Implements retry logic for deadlocks, update conflicts, and transient SQL errors.
/// </summary>
/// <param name="_processId">Process identifier created and added in the contract <c>METCPIRepricingContract</c>.</param>
/// <param name="_readPast">Boolean flag to determine if past records should be read.</param>
/// <returns>True if a Sales Order was retrieved from the queue; otherwise, false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METCPIRepricingQueue topPickingQueue;
    int backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            salesId = topPickingQueue.SalesId;
            topPickingQueue.delete();
        }
        else
        {
            salesId = METConstants::emptyString;
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (salesId != METConstants::emptyString);
}

/// <summary>
/// Executes CPI repricing logic for the current Sales Order.
/// Resets line-level pricing, cancels bonus lines, deletes price components,
/// and updates the Sales Order header to Ready for Pricing with CPIRepriced flag set.
/// </summary>
private void execute()
{
    const int METRetryNum = 2;
    SalesLine                    salesLine;
    METSalesLine                 metSalesLine;
    METInventTable               metInventTable;

    SalesTable salesTable = SalesTable::find(salesId);

    setPrefix(strFmt("@MET:CPISOPricing %1", salesTable.SalesId));

    if (salesTable.METOrderExtractStatus == METOrderExtractStatus::Open)
    {
        try
        {            
            // Bug 416940: Manage Legislative Charges - Error in in CPI Sales order Repricing batch job
            // Broke down the 1 long single transactions into 4 smaller transactions to avoid deadlocks and update conflicts
            // Removed forupdate locks, unnecessary loops and multiple db trips

            // Delete the components for entire order
            if (cpIFlag)
            {   
                salesTable.metCPIDeletePriceComponents();
                // Cancel bonus lines (should not be that many)
                // Note the cancellation will trigger Dual Write
                while select salesLine
                join  metSalesLine
                 where salesLine.SalesId == salesId
                    && metSalesLine.SalesLine == salesLine.RecId
                    && metSalesLine.BonusType == METBonusType::DiscountBonus
                    && salesLine.SalesStatus != SalesStatus::Canceled
                      exists join METInventTable
                        where METInventTable.ItemId == salesLine.ItemId
                            && METInventTable.METTariffItemCodeBaseRecid != 0
                {
                    salesLine.metCancelSalesOrderLine();
                }

                // Update the flag for Repricing to A or U based on the indicator
                ttsbegin;
                while select salesLine
                join forupdate metSalesLine
                 where salesLine.SalesId == salesId
                    && metSalesLine.SalesLine == salesLine.RecId
                    && salesLine.SalesStatus != SalesStatus::Canceled
                {
                    metSalesLine.Indicators  = METInventTable::find(salesLine.ItemId).METTariffItemCodeBaseRecid != 0 ? METConstants::A : METConstants::U;
                    metSalesLine.update();
                }
                ttscommit;
            }
            else
            {   
                salesTable.metDeletePriceComponents();

                // Cancel bonus lines (should not be that many)
                // Note the cancellation will trigger Dual Write
                while select salesLine
                join metSalesLine
                 where salesLine.SalesId == salesId
                    && metSalesLine.SalesLine == salesLine.RecId
                    && metSalesLine.BonusType == METBonusType::DiscountBonus
                    && salesLine.SalesStatus != SalesStatus::Canceled
                {
                    salesLine.metCancelSalesOrderLine();
                }

                // Update the flag for Repricing to A
                ttsbegin;
                while select salesLine
                join forupdate metSalesLine
                 where salesLine.SalesId == salesId
                    && metSalesLine.SalesLine == salesLine.RecId
                    && salesLine.SalesStatus != SalesStatus::Canceled
                {
                    metSalesLine.Indicators = METConstants::A;
                    metSalesLine.update();
                }
                ttscommit;

            }

            // Update pre-quota qty
            // Note the OrderedQuantity will trigger Dual Write
            ttsbegin;
            update_recordset salesLine
                setting SalesQty = metSalesLine.OrderedQuantity
                join metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                        && salesLine.SalesId == salesId;
            ttscommit;

            // Update SalesTable header
            ttsbegin;
            METSalesTable metSalesTable = salesTable.metSalesTable();

            metSalesTable.selectForUpdate(true);
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.CPIRepriced = NoYes::Yes;
            metSalesTable.update();

            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= METRetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= METRetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }        
}
